def _move(self, state, action):
    """纯查询：返回 (new_state, reward, done)。"""
    if self._cell(state) == "G":
        return state, 0, True
    dr, dc = _ACTIONS[action]
    nxt = (state[0] + dr, state[1] + dc)
    if not self._in_bounds(nxt) or self._cell(nxt) == "#":
        return state, -1, False
    if self._cell(nxt) == "G":
        return nxt, 0, True
    return nxt, -1, False

